// Extract the tool_use block. Guardrail: only search_company_knowledge is a
// recognized/enabled tool in Phase 2 — anything else is denied, not executed.
const resp = $json;
const toolBlock = (resp.content || []).find(b => b.type === 'tool_use');
if (!toolBlock) { throw new Error('Expected tool_use block but none found'); }

const ALLOWED_TOOLS = ['search_company_knowledge'];
const decision = ALLOWED_TOOLS.includes(toolBlock.name) ? 'auto_approved' : 'denied_by_policy';

return [{ json: {
  tool_name: toolBlock.name,
  tool_input: toolBlock.input,
  tool_use_id: toolBlock.id,
  decision
}}];

// Format the sub-workflow's retrieval results as a Claude tool_result block
// and append it to the running message history for a second Claude call.
const priorMessages = $('Build Claude Request').first().json.claude_messages;
const claudeTurn1 = $('Call Claude (turn 1)').first().json;
const toolCall = $('Extract Tool Call').first().json;
const results = $input.all().map(r => r.json);

const resultText = results.length
  ? results.map(r => `[source: ${r.section_ref || r.document_id}] ${r.content}`).join('\n\n')
  : 'No relevant results found in the knowledge base.';

const updatedMessages = [
  ...priorMessages,
  { role: 'assistant', content: claudeTurn1.content },
  { role: 'user', content: [{ type: 'tool_result', tool_use_id: toolCall.tool_use_id, content: resultText }] }
];

return [{ json: { ...$('Merge Tenant Context').first().json, claude_messages: updatedMessages, system_prompt: $('Build Claude Request').first().json.system_prompt } }];

// Merge point: whichever path produced the final assistant text (direct answer,
// or answer after a tool round-trip) — extract the plain text for logging/response.
const resp = $json;
const textBlock = (resp.content || []).find(b => b.type === 'text');
return [{ json: { final_text: textBlock ? textBlock.text : '', raw: resp } }];

// Tool call was denied by policy (not on the allow-list). Do NOT execute it.
// Return a safe fallback message instead of the tool result.
return [{ json: { final_text: "I'm not able to do that directly, but I can pass this along to the team." } }];
